import subprocess

def check_pdfunite_installed():
    try:
        subprocess.run(['pdfunite', '--version'], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        print("pdfunite is installed.")
    except subprocess.CalledProcessError:
        print("pdfunite is not installed or not in PATH.")

check_pdfunite_installed()
